const CRVPF_LOGO_URL='https://crvpf.org/wp-content/uploads/2025/01/CRPVF_Final_Logo-08.png';
const CRVPF_INTRO="Children's Rights and Violence Prevention Fund (CRVPF) is a child rights and social justice regional intermediary organization that partners with community organizations to prevent violence and sexual violence against children and young people, building their power to make the right choices and decisions, and facilitating safe and dignified employment opportunities. CRVPF operates in Uganda, Kenya, Tanzania and Ethiopia.";
const CRVPF_VISION='A world where children and young people are safe from violence and sexual violence in the places where they live, learn, play, and work.';
const CRVPF_MISSION='To advance the safety and rights of children and young people by working with community organizations through cluster partnerships.';
const CRVPF_GOAL='Create safe and empowering environments in schools, homes, and communities across Kenya, Uganda, Ethiopia, and Tanzania.';
type Program = { slug:string; short:string; name:string; summary:string; details:string[] };
const programs:Program[]=[
 {slug:'/programmes/pvac',short:'PVAC',name:'Prevention of Violence against Children and Young People (pvac)',summary:'Violence against children and young people takes place at home, in schools, and in the community. Under the PVAC program, we partner with and strengthen the capacity of community organizations to deliver a holistic set of interventions. These include building the capabilities of both formal and informal structures to create safe and supportive environments for children and young people.',details:['Strengthening families’ capabilities through positive parenting and improved spousal relationships to create safe and nurturing environments for children and young people. We also increase access to financial services to help reduce the financial stress within families that can escalate violence against children and young people.','In schools, students, non-teaching staff, and teachers are provided with the necessary skills and knowledge to create environments free from all forms of violence, including bullying, corporal punishment, and inappropriate relationships with staff, to help facilitate successful learning.','In the community, safe spaces are created for young people who are not in school to come together and acquire life and income-generating skills, thereby equipping them with skills and knowledge for preventing and addressing violence and sexual violence.','Parents strengthened their parenting skills and spousal relationships using the Parenting for Respectability manual, a locally evidence-based parenting program developed by the Child Health Development Centre at Makerere University.']},
 {slug:'/programmes/agpp',short:'AGPP',name:'Adolescent Girls Power Program (AGPP)',summary:'The Adolescent Girls Power Program (AGPP) focuses on building power of adolescent girls, including young mothers, to enable them transform and change the structures that deny them choices and power. CRVPF community partners work with the girls to create safe spaces; platforms in the community where the girls come together to engage in dialogue with one another, and receive life skills, financial literacy, vocational training to generate their own income to reduce the likelihood of violence and sexual violence.',details:['During the COVID-19 pandemic the lives of adolescent girls were heavily impacted, with many young girls in the Sub-Saharan region becoming young mothers. As a result, CRVPF developed a special project in Kenya and Tanzania to address this increase. The Young Mothers Project (YMP) equips young mothers with a comprehensive set of life skills and vocational training designed to build their power, while also providing Early Childhood Development (ECD) services for their children aged 0-3 years.','Collectively the girls develop strategies and advocate for their rights for a life free from violence and sexual violence.']},
 {slug:'/programmes/eydcd',short:'EYDCD',name:'Empowering Youth Through Data and Community Development Program (EYDCD)',summary:'Empowering Youth through Data and Community Development (EYDCD) program is a five-year program led by Children’s Rights and Violence Prevention Fund (CVRPF) and gnuGrid CRB in partnership with Mastercard Foundation. The program aims to provide market-relevant skills, business development resources, and digital financial inclusion to empower young people in Uganda. Throughout its duration, the program will endeavour to reach 400,000 young people across the country (70% female) and create 250,000 dignified and fulfilling employment opportunities.',details:['Additionally, the program will strengthen the capacities of 200 community organizations to deliver training and capacity-building programs that link young people, including those in refugee and host communities, and people with disabilities to work opportunities.','By digitizing 3,000 youth-led Village Savings and Loan Associations (VSLAs) and creating digital wallets for their members, the program aims to enhance access to financial services and products from local financial institutions.']},
];
const pages=[
 ['/','Home'],['/about','About'],['/programmes/pvac','PVAC'],['/programmes/agpp','AGPP'],['/programmes/eydcd','EYDCD'],['/programmes/coordinated','Coordinated'],['/programmes/joint','Joint'],['/impact','Impact'],['/annual-report-2026','Annual Report'],['/partners','Partners'],['/donor-portal','Donor Portal'],['/dashboard','Dashboard'],['/admin-demo','Safeguarding CMS'],['/publications','Publications'],['/training','Training'],['/handover','Handover'],['/financial','Financial'],['/contact','Contact'],
] as const;
const storyData=[
 {name:'Beatrice',country:'Uganda',program:'EYDCD',text:'Beatrice, 28, a graduate of Business and Administration, wife, and mother of two, was one of them. Despite her education, she struggled to find stable work. However, with resilience and a desire to create impact, she turned to a skill her mother had once taught her, basket weaving. Through the program, Beatrice and her peers received financial literacy training and formed a Village Savings and Loan Association (VSLA), which they named One Voice Savings Group. They now meet every Saturday, each saving at least UGX 1,000. Together, they opened a bank account, formalized leadership, and established a welfare fund, turning their group into a lifeline for women in moments of vulnerability. The women went on to form Kyisa Kya Maria Arts and Crafts Group, where Beatrice continues to train and mentor others.',quote:'We got a client, All Across Africa, who sends us designs. We weave the baskets and send them back to be exported. The money we earn helps, because when there are no orders, some women can’t afford to send their children to school.',href:'https://crvpf.org/baskets-bonds-and-bold-women-a-story-of-sisterhood-and-strength/'},
 {name:'The Dar-Girls',country:'Tanzania',program:'AGPP',text:'Mariam, Jennifer, Zawadi, and Francisa—four young girls, each with dreams of independence and wealth that went beyond money—were unaware of each other but were all introduced to KIWOHEDE’s program, supported by CRVPF, through various channels including neighbours, radio ads, posters, and more. When the girls, along with several other young women, joined the program, they were equipped with life skills from This Little Light of Mine, a manual developed by CRVPF to help adolescent girls make smart choices and informed decisions, which enable them to lead safe, dignified, and sustainable lives free from violence and sexual violence.',href:'https://crvpf.org/bold-movements/'},
 {name:'Joanita (Joanna) Nabagesera',country:'Uganda',program:'EYDCD',text:'The usually quiet grounds of Express Playground in Kyebando, Kampala, came alive one sunny afternoon in March as drums echoed across the field and young designers prepared backstage for the Pakasa Art and Fashion Showcase, held in celebration of International Women’s Day 2026. Led by Joanita (Joanna) Nabagesera, founder and CEO of Lulungi Couture and an alumna of the Empowering Youth Through Data and Community Development (EYDCD) program implemented by CRVPF, gnuGrid CRB and community partners, with support from Mastercard Foundation, the showcase brought together young designers, artists, community members, and local leaders to celebrate creativity as a pathway to entrepreneurship, inclusion, and economic opportunity for young women and youth in the community.',href:'https://crvpf.org/edition-2-2026/'},
 {name:'Doreen Ngobi',country:'Uganda',program:'AGPP',text:'Through the Safe Space intervention under CRVPF’s Adolescent Girls Power Program (AGPP), Doreen learned hairdressing, snack making, flower weaving, marketing, saving, and leadership skills alongside other girls and young mothers.',quote:'Just because you are a teen mother does not mean your life is over. You can still achieve your dreams and become someone in life.',href:'https://crvpf.org/edition-2-2026/'},
 {name:'Juma',country:'',program:'PVAC',text:'Through the Father on Duty movement under CRVPF’s Prevention of Violence against Children and Young People (PVAC) program, fathers gather in spaces where men speak openly with other men about parenting, relationships, pressure, anger, and responsibility.',quote:'Father on Duty taught me that being a man means caring, listening, and protecting my family without violence.',href:'https://crvpf.org/edition-2-2026/'},
 {name:'Priscilla Kirabo',country:'Uganda',program:'EYDCD',text:'EYDCD Youth Representative Priscilla Kirabo encouraged young people to use digital tools strategically to generate income and build livelihoods.',href:'https://crvpf.org/edition-2-2026/'},
];
const countries=['Uganda','Kenya','Tanzania','Ethiopia'];
const reportItems=['READ OUR 2025 ABRIDGED ANNUAL REPORT','Annual Report CRVPF 2025','Annual Report CRVPF 2024','Annual Report CRVPF 2023','Annual Report CRVPF 2022','Annual Report CRVPF 2021','Annual Report CRVPF 2020','Assessment Impact COVID 19','BOLD MOVEMENTS — Celebrating 10 years of impact!','Edition 2, 2026'];
const reportUrls=['https://drive.google.com/file/d/1Cy8YmNVu8h_7RjSkY8vwjebB3J-TYvTX/view?usp=drive_link','https://drive.google.com/file/d/10VWKaeQZ_f6WZPTD-_EHz46cw7kh-Pji/view','https://drive.google.com/file/d/16gdye6D8b7x4ZDH612-udJu9Z4OGf9LD/view?usp=drive_link','https://crvpf.org/wp-content/uploads/2025/02/CRVPFAnnualReport_2023_compressed.pdf','https://crvpf.org/wp-content/uploads/2025/02/CRVPFAnnualReport_2022.pdf','https://crvpf.org/wp-content/uploads/2025/02/CRVPFAnnualReport_2021.pdf','https://crvpf.org/wp-content/uploads/2025/02/CRVPFAnnualReport_2020.pdf','https://crvpf.org/wp-content/uploads/2025/08/CRVPF-Impact-of-COVID-report_2022.pdf','https://crvpf.org/bold-movements/','https://crvpf.org/edition-2-2026/'];
const programmeFilters=['All','PVAC','AGPP','EYDCD','Coordinated','Joint'];
const socialLinks=[
 {name:'Facebook',url:'https://www.facebook.com/CRVPF/',icon:FaFacebookF},
 {name:'LinkedIn',url:'https://www.linkedin.com/company/children-s-rights-and-violence-prevention-fund-crvpf/',icon:FaLinkedinIn},
 {name:'X',url:'https://x.com/crvpf1?s=21',icon:FaXTwitter},
 {name:'Instagram',url:'https://www.instagram.com/crvpf?igsh=MWI5ZjdqN2N1dTZ4Yw==',icon:FaInstagram},
 {name:'YouTube',url:'https://www.youtube.com/@childrensrightsandviolence3853',icon:FaYoutube},
];
type AdminStory={id:string;title:string;country:string;programme:string;story:string;status:string;anonymous?:boolean;audit?:string};
function loadAdminStories():AdminStory[]{try{const value=JSON.parse(localStorage.getItem('crvpf-admin-items')||'[]');if(!Array.isArray(value))return[];return value.map((item:any,index:number)=>typeof item==='string'?{id:`legacy-${index}`,title:item,country:'',programme:'',story:'',status:'Published'}:item).filter((item:any)=>item&&typeof item.title==='string')}catch{return[]}}

function App(){
 const [path,setPath]=useLocation();
 const [lang,setLang]=useState<'EN'|'SW'>(()=>(localStorage.getItem('crvpf-lang') as 'EN'|'SW')||'EN');
 const [menu,setMenu]=useState(false),[programOpen,setProgramOpen]=useState(false),[search,setSearch]=useState(false),[searchText,setSearchText]=useState('');
 const [donate,setDonate]=useState(false),[toast,setToast]=useState(''),[selectedCountry,setSelectedCountry]=useState('All'),[selectedProgram,setSelectedProgram]=useState('All');
  const [year,setYear]=useState(2026),[portalTab,setPortalTab]=useState('My Grants'),[login,setLogin]=useState(false);
  const [adminItems,setAdminItems]=useState<AdminStory[]>(loadAdminStories);
 const [pubModal,setPubModal]=useState('');
 const notify=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(''),4000)};
 useEffect(()=>{setMenu(false);setProgramOpen(false);if(window.location.hash){const id=decodeURIComponent(window.location.hash.slice(1));requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({block:'start'}))}},[path]);
 useEffect(()=>{localStorage.setItem('crvpf-lang',lang)},[lang]);
  const filteredPages=useMemo(()=>{
    const source=[...pages.map(([url,label])=>({url,label,text:`${url} ${label} ${programs.find(p=>p.slug===url)?.name||''}`})),...programs.map(p=>({url:p.slug,label:p.short,text:`${p.name} ${p.summary} ${p.details.join(' ')}`})),{url:'/programmes/coordinated',label:'Coordinated',text:`${approachContent.coordinated.title} ${approachContent.coordinated.summary}`}, {url:'/programmes/joint',label:'Joint',text:`${approachContent.joint.title} ${approachContent.joint.summary}`},...storyData.map(s=>({url:`/impact#story-${s.name.toLowerCase().replaceAll(' ','-')}`,label:s.name,text:`${s.name} ${s.country} ${s.program} ${s.text}`})),...countries.map(c=>({url:`/impact#filter-country-${c.toLowerCase()}`,label:c,text:c})),...reportItems.map((t,i)=>({url:`/publications#publication-${i}`,label:t,text:t}))];
  const q=searchText.trim().toLowerCase();return q?source.filter(x=>x.text.toLowerCase().includes(q)).filter((x,i,a)=>a.findIndex(y=>y.url===x.url&&y.label===x.label)===i):pages.map(([url,label])=>({url,label}));
 },[searchText]);
 const donateAction=()=>setDonate(true);
  const footer=<Footer onDonate={donateAction}/>;
 return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}>
  <div className="app-shell">
     <div className="top-banner" data-testid="text-demo-banner">DEMO ON REPLIT - PROOF OF CONCEPT by ELITECH TECHNOLOGIES - Lead: Akol Francis, 0781155288. Built on Replit to prove system works. Final site will be WordPress + Elementor on i3C per TOR. All content from crvpf.org. No live data. All publishing requires CRVPF Communications approval.</div>
     <LowNetworkBanner />
    <Header path={path} lang={lang} programOpen={programOpen} onProgramToggle={()=>setProgramOpen(v=>!v)} onLanguage={setLang} onDonate={donateAction} onSearch={()=>setSearch(true)} onMenu={()=>setMenu(true)} />
    {menu&&<MobileDrawer lang={lang} onLanguage={setLang} onClose={()=>setMenu(false)} onSearch={()=>{setMenu(false);setSearch(true)}} onDonate={donateAction}/>}
   <Switch>
     <Route path="/"><Home lang={lang} notify={notify} selectedCountry={selectedCountry} setCountry={setSelectedCountry} /></Route>
    <Route path="/about"><About /></Route>
    <Route path="/programmes/pvac"><ProgrammeDetail slug="/programmes/pvac" notify={notify}/></Route>
    <Route path="/programmes/agpp"><ProgrammeDetail slug="/programmes/agpp" notify={notify}/></Route>
    <Route path="/programmes/eydcd"><ProgrammeDetail slug="/programmes/eydcd" notify={notify}/></Route>
    <Route path="/programmes/coordinated"><ProgrammeDetail slug="/programmes/coordinated" notify={notify}/></Route>
    <Route path="/programmes/joint"><ProgrammeDetail slug="/programmes/joint" notify={notify}/></Route>
    <Route path="/impact"><Impact country={selectedCountry} setCountry={setSelectedCountry} program={selectedProgram} setProgram={setSelectedProgram}/></Route>
    <Route path="/annual-report-2026"><Annual notify={notify}/></Route>
    <Route path="/partners"><Partners tab={portalTab} setTab={setPortalTab} login={login} setLogin={setLogin} notify={notify}/></Route>
    <Route path="/dashboard"><Dashboard year={year} setYear={setYear} country={selectedCountry} setCountry={setSelectedCountry} notify={notify}/></Route>
     <Route path="/admin-demo"><Admin items={adminItems} onPublish={(item)=>{const next=[item,...adminItems];setAdminItems(next);localStorage.setItem('crvpf-admin-items',JSON.stringify(next))}} notify={notify}/></Route>
     <Route path="/publications"><Publications /></Route>
    <Route path="/training"><Training notify={notify}/></Route>
    <Route path="/handover"><Handover notify={notify}/></Route>
    <Route path="/financial"><Financial /></Route>
    <Route path="/donor-portal"><DonorPortal notify={notify} onDonate={donateAction}/></Route>
    <Route path="/contact"><Contact notify={notify}/></Route>
     <Route path="/system"><SystemPage /></Route>
     <Route path="/how-we-deliver"><HowWeDeliver /></Route>
    <Route><NotFound /></Route>
   </Switch>
   {footer}
   <nav className="mobile-bottom" aria-label="Quick navigation">
    <Link href="/" data-testid="mobile-home"><HomeIcon size={18}/><span>Home</span></Link>
    <Link href="/programmes/pvac" data-testid="mobile-programmes"><Shield size={18}/><span>Programmes</span></Link>
    <Link href="/impact" data-testid="mobile-stories"><BookOpen size={18}/><span>Stories</span></Link>
    <button className="donate-tab" onClick={donateAction} data-testid="mobile-donate"><HandHeart size={18}/><span>Donate</span></button>
   </nav>
    {search&&<SearchModal value={searchText} setValue={setSearchText} results={filteredPages} onStorySelect={()=>{setSelectedCountry('All');setSelectedProgram('All')}} onClose={()=>{setSearch(false);setSearchText('')}}/>}
   {donate&&<DonateModal onClose={()=>setDonate(false)} notify={notify}/>}
    {pubModal&&<Modal title={pubModal} onClose={()=>setPubModal('')}><p>You selected “{pubModal}”. This standalone demo identifies the publication but does not provide a downloadable file.</p><div className="notice">No report download or publication action is available in this demo.</div></Modal>}
   <BackToTop />
   {toast&&<div className="toast" role="status" data-testid="status-toast">{toast}</div>}
  </div>
 </WouterRouter>
}

function Header({path,lang,programOpen,onProgramToggle,onLanguage,onDonate,onSearch,onMenu}:{path:string;lang:'EN'|'SW';programOpen:boolean;onProgramToggle:()=>void;onLanguage:(v:'EN'|'SW')=>void;onDonate:()=>void;onSearch:()=>void;onMenu:()=>void}){
 const sw=lang==='SW';
 const link=(url:string,label:string,translated:string=label)=><Link href={url} className={`nav-link ${path===url?'active':''}`} data-testid={`nav-${label.toLowerCase().replaceAll(' ','-')}`}>{sw?translated:label}</Link>;
 return <header className="site-header"><div className="header-inner">
     <Link href="/" className="brand" aria-label="CRVPF home" data-testid="link-brand"><img className="brand-logo" src={CRVPF_LOGO_URL} alt="CRVPF logo" width="11309" height="4010" fetchPriority="high" decoding="async"/></Link>
  <nav className="desktop-nav" aria-label="Main navigation">
    {link('/about','About','Kuhusu')}
     <div className={`program-wrap ${programOpen?'open':''}`} onBlur={e=>{if(programOpen&&!e.currentTarget.contains(e.relatedTarget as Node|null))onProgramToggle()}} onKeyDown={e=>{if(e.key==='Escape'&&programOpen){onProgramToggle();(e.currentTarget.querySelector('.program-trigger') as HTMLButtonElement|null)?.focus()}}}><button type="button" className={`nav-link program-trigger ${path.includes('/programmes')?'active':''}`} onClick={onProgramToggle} aria-expanded={programOpen} aria-haspopup="true" data-testid="nav-our-work">{sw?'Kazi Yetu':'Our Work'}</button><div className="program-menu">{[...programs.map(p=>({url:p.slug,label:`${p.short} · ${p.name}`})),{url:'/programmes/coordinated',label:'Coordinated Program Approach'},{url:'/programmes/joint',label:'Joint Program Approach'}].map(p=><Link key={p.url} href={p.url} data-testid={`nav-program-${p.url.split('/').pop()}`}>{p.label}</Link>)}</div></div>
     {link('/impact','Impact','Athari')}{link('/publications','Resources','Rasilimali')}{link('/annual-report-2026','News','Habari')}{link('/partners','Get Involved','Shiriki')}
  </nav>
   <div className="header-actions"><SocialLinks className="header-social"/><button className="icon-btn" aria-label="Search site" onClick={onSearch} data-testid="button-search"><Search size={19}/></button><div className="lang-toggle" aria-label="Language"><button onClick={()=>onLanguage('EN')} className={lang==='EN'?'selected':''} data-testid="language-en">EN</button><button onClick={()=>onLanguage('SW')} className={lang==='SW'?'selected':''} data-testid="language-sw">SW</button></div><button className="btn btn-orange" onClick={onDonate} data-testid="button-donate">{sw?'Changia':'Donate'}</button><button className="icon-btn menu-toggle" aria-label="Open navigation" onClick={onMenu} data-testid="button-menu"><Menu size={24}/></button></div>
 </div></header>
}

function MobileDrawer({onClose,onDonate,onSearch,lang,onLanguage}:{onClose:()=>void;onDonate:()=>void;onSearch:()=>void;lang:'EN'|'SW';onLanguage:(v:'EN'|'SW')=>void}){
 const [open,setOpen]=useState(false);const sw=lang==='SW';
    return <div className="mobile-drawer" role="dialog" aria-modal="true" aria-label="Navigation menu"><div className="drawer-head"><Link href="/" className="brand" onClick={onClose}><img className="brand-logo" src={CRVPF_LOGO_URL} alt="CRVPF logo" width="11309" height="4010" decoding="async"/></Link><button className="icon-btn" onClick={onClose} aria-label="Close menu" data-testid="button-close-menu"><X size={24}/></button></div>
   <div className="drawer-links">
    <button className="drawer-accordion" onClick={onSearch} data-testid="drawer-search"><span>{sw?'Tafuta':'Search'}</span><Search size={18}/></button>
     <Link href="/about" onClick={onClose} data-testid="drawer-about">{sw?'Kuhusu':'About'}</Link><button className="drawer-accordion" onClick={()=>setOpen(!open)} aria-expanded={open} data-testid="drawer-programmes">{sw?'Kazi Yetu':'Our Work'} <ChevronDown size={18}/></button>{open&&<div className="drawer-sub">{[...programs.map(p=>({url:p.slug,label:`${p.short} — ${p.name}`})),{url:'/programmes/coordinated',label:'Coordinated Program'},{url:'/programmes/joint',label:'Joint Program'}].map(p=><Link key={p.url} href={p.url} onClick={onClose}>{p.label}</Link>)}</div>}
     <Link href="/impact" onClick={onClose} data-testid="drawer-impact">{sw?'Athari':'Impact'}</Link><Link href="/publications" onClick={onClose} data-testid="drawer-resources">Resources</Link><Link href="/annual-report-2026" onClick={onClose} data-testid="drawer-news">News</Link><Link href="/partners" onClick={onClose} data-testid="drawer-partners">Get Involved</Link><Link href="/dashboard" onClick={onClose} data-testid="drawer-dashboard">Dashboard</Link><Link href="/admin-demo" onClick={onClose} data-testid="drawer-cms">Safeguarding CMS</Link><Link href="/training" onClick={onClose}>Training</Link><Link href="/handover" onClick={onClose}>Handover</Link><Link href="/financial" onClick={onClose}>Financial</Link><Link href="/contact" onClick={onClose} data-testid="drawer-contact">{sw?'Mawasiliano':'Contact'}</Link>
   </div>
   <div className="drawer-actions"><button className="btn btn-orange" onClick={()=>{onClose();onDonate()}}>{sw?'Changia':'Donate'} <HandHeart size={16}/></button><div className="lang-toggle"><button className={lang==='EN'?'selected':''} onClick={()=>onLanguage('EN')}>EN</button><button className={lang==='SW'?'selected':''} onClick={()=>onLanguage('SW')}>SW</button></div></div><SocialLinks className="drawer-social"/>
 </div>
}
function SocialLinks({className=''}:{className?:string}){return <div className={`social-links ${className}`}>{socialLinks.map(({name,url,icon:Icon})=><a key={name} href={url} target="_blank" rel="noopener noreferrer" aria-label={`CRVPF on ${name}`} title={name}><Icon size={16}/></a>)}</div>}
 function Footer({onDonate}:{onDonate:()=>void}){return <footer className="site-footer"><div className="container"><div className="footer-grid"><div><Link href="/" className="brand footer-brand"><img className="brand-logo" src={CRVPF_LOGO_URL} alt="CRVPF logo" width="11309" height="4010" loading="lazy" decoding="async"/></Link><p style={{maxWidth:300,marginTop:19}}>{CRVPF_INTRO}</p><button className="btn btn-green" onClick={onDonate}>Donate</button></div><div><h4>Explore</h4><Link href="/about">About CRVPF</Link><Link href="/impact">Impact &amp; stories</Link><Link href="/partners">Partner portal</Link><Link href="/donor-portal">Donor portal</Link><Link href="/dashboard">Dashboard demo</Link><Link href="/training">Training Hub</Link><Link href="/handover">Handover</Link><Link href="/financial">Financial</Link><Link href="/system">System Analysis</Link><Link href="/how-we-deliver">How We Deliver</Link></div><div><h4>Programmes</h4>{programs.map(p=><Link key={p.slug} href={p.slug}>{p.short}</Link>)}<Link href="/programmes/coordinated">Coordinated</Link><Link href="/programmes/joint">Joint</Link><Link href="/publications">Publications</Link></div><div><h4>Contact</h4><p><a href="tel:+256393216519">(+256) 393 216 519</a><a href="mailto:info@crvpf.org">info@crvpf.org</a>Block 244, Plot 5170, Diplomate Road, Muyenga, Kampala, Uganda</p><a className="btn btn-green whatsapp-link" href="https://wa.me/256393216519" target="_blank" rel="noopener noreferrer">WhatsApp CRVPF</a><Link href="/contact">Send a message <ArrowRight size={13}/></Link></div></div><SocialLinks className="footer-social"/><ElitechStudios title="Powered by ELITECH TECHNOLOGIES - Our Studios"/><div className="footer-bottom">Demo on Replit | Final on WordPress + Elementor + i3C | Powered by ELITECH TECHNOLOGIES - Building systems that work for real people in Uganda. Lead: Akol Francis, 0781155288, <a href="mailto:akolfrancis85@gmail.com" className="inline-contact">akolfrancis85@gmail.com</a></div><p className="footer-operations">Demo on Replit. Content sourced from crvpf.org; publishing requires CRVPF communications approval.</p></div></footer>}
function SectionHead({eyebrow,title,description}:{eyebrow:string;title:string;description?:string}){return <div className="section-head"><div><div className="section-kicker">{eyebrow}</div><h2>{title}</h2></div>{description&&<p>{description}</p>}</div>}
function Home({lang,notify,selectedCountry,setCountry}:{lang:'EN'|'SW';notify:(s:string)=>void;selectedCountry:string;setCountry:(country:string)=>void}){
 const [email,setEmail]=useState(''),[newsletterOpen,setNewsletterOpen]=useState(false),[officeOpen,setOfficeOpen]=useState(false);const sw=lang==='SW';
 const submitNewsletter=(e:FormEvent)=>{e.preventDefault();if(!email.includes('@')){notify('Enter a valid email address.');return}notify('Demo signup - will connect to CRVPF Mailchimp on approval.')};
  const visibleStories=storyData.filter(s=>selectedCountry==='All'||s.country===selectedCountry);
  const opportunities=[['PVAC','/programmes/pvac',programs[0].summary],['AGPP','/programmes/agpp',programs[1].summary],['EYDCD','/programmes/eydcd',programs[2].summary],['Coordinated','/programmes/coordinated',approachContent.coordinated.summary],['Joint','/programmes/joint',approachContent.joint.summary]];
 return <main>
   <section className="hero"><div className="hero-copy"><div className="eyebrow">{sw?'Haki za watoto · Uwezo wa jamii':'Children’s Rights and Violence Prevention Fund (CRVPF)'}</div><h1>{sw?'Kumaliza ukatili, kujenga uwezo':'Ending Violence,'}<br/><em>{sw?'Kujenga uwezo':'Building Power'}</em></h1><p className="hero-vision">{sw?'Dunia ambamo watoto na vijana wako salama dhidi ya ukatili na ukatili wa kingono wanapoishi, kujifunza, kucheza na kufanya kazi.':'A world where children and young people are safe from violence and sexual violence in the places where they live, learn, play, and work.'}</p><div className="hero-cta"><Link className="btn btn-orange" href="/#programmes" data-testid="button-home-programmes">{sw?'Programu Zetu':'Our Programmes'} <ArrowRight size={17}/></Link><Link className="btn btn-outline" href="/impact" data-testid="button-home-impact">{sw?'Jifunze kuhusu athari':'Learn About Our Impact'}</Link></div></div><div className="hero-art"><SourcePhoto src="https://crvpf.org/wp-content/uploads/elementor/thumbs/g4-r45jk88io3s6brnc62htrycwefcr0hlk2fdu0yjbdk.jpg" alt="CRVPF community photo from the homepage" className="hero-photo"/><span className="art-label">Source: crvpf.org</span></div></section>
    <section className="metrics"><div className="container metric-row metric-row-three"><div className="metric"><AnimatedMetric value={1330}/><span>Program participants · 2021–2023</span></div><div className="metric"><AnimatedMetric value={253}/><span>Young people engaged in dignified and fulfilling work as entrepreneurs or formally employed</span></div><div className="metric"><AnimatedMetric value={88}/><span>Parents participating in weekly savings and lending meetings to increase household incomes</span></div><small className="source-note">Source: crvpf.org</small></div></section>
    <section className="section"><div className="container"><SectionHead eyebrow="WELCOME" title="Vision, Mission & Goal" description={CRVPF_INTRO}/><div className="content-grid"><div className="prose"><h3>Our Vision</h3><p>{CRVPF_VISION}</p><h3>Mission</h3><p>{CRVPF_MISSION}</p></div><div className="soft-card"><span className="tag">Goal</span><p style={{fontSize:19,fontWeight:700,color:'var(--blue)',lineHeight:1.5}}>{CRVPF_GOAL}</p><Link href="/about" className="arrow-link">About CRVPF <ArrowRight size={15}/></Link></div></div></div></section>
   <section id="programmes" className="section tight" style={{background:'var(--sky)'}}><div className="container"><SectionHead eyebrow="Our programs" title="Our Programs" description="Source: crvpf.org/our-programs/ and crvpf.org/our-approaches/"/><div className="program-grid">{opportunities.map(([label,url,summary],i)=><article className="program-card" key={label}><span className="number">0{i+1} / {label}</span><h3>{label}</h3><p>{summary}</p><Link className="arrow-link" href={url}>Explore programme <ArrowRight size={15}/></Link></article>)}</div></div></section>
   <section className="story-strip"><div className="container"><SectionHead eyebrow="Community stories" title="Stories from the work" description="Select a country on the map to filter these documented stories."/><div className="story-country-filter"><span>Country:</span><button className={selectedCountry==='All'?'active':''} onClick={()=>setCountry('All')}>All</button>{countries.map(c=><button className={selectedCountry===c?'active':''} key={c} onClick={()=>setCountry(c)}>{c}</button>)}</div>{visibleStories.length?<div className="story-grid">{visibleStories.map((s,i)=><StoryCard s={s} i={i} key={s.name}/>)}</div>:<div className="empty-state">No supplied stories for {selectedCountry}. Try another country.</div>}<div className="story-image-feature"><SourcePhoto src="https://crvpf.org/wp-content/uploads/elementor/thumbs/AGPP-adolescent-girls-1-scaled-r45jk88io3s6brnc62htrycwefcr0hlk2fdu0yjbdk.jpg" alt="CRVPF photo labeled AGPP adolescent girls on the homepage" className="story-photo"/><div><span className="tag">Source: crvpf.org</span><h3>CRVPF community photo</h3><p>This photo is published on CRVPF’s homepage and is not attributed to a named story.</p><Link className="arrow-link" href="/impact">Browse impact stories <ArrowRight size={15}/></Link></div></div><div className="quote-grid"><blockquote>“Just because you are a teen mother does not mean your life is over. You can still achieve your dreams and become someone in life.” — Doreen</blockquote><blockquote>“Father on Duty taught me that being a man means caring, listening, and protecting my family without violence.” — Juma</blockquote></div><div style={{textAlign:'center',marginTop:28}}><Link className="btn btn-blue" href="/impact">Explore all stories <ArrowRight size={16}/></Link></div></div></section>
  <section className="section"><div className="container"><MapPanel onPin={setCountry} selectedCountry={selectedCountry} onOffice={()=>setOfficeOpen(true)}/><div className="map-story-link"><Link className="arrow-link" href="/impact">View stories by country <ArrowRight size={15}/></Link></div></div></section>
   <section className="section tight"><div className="container"><div className="report-banner"><div><span className="eyebrow">Annual Reports</span><h3>READ OUR 2025 ABRIDGED ANNUAL REPORT</h3><p>Annual Report CRVPF 2025 · Annual Report CRVPF 2023</p><div className="report-link-row"><a href={reportUrls[1]} target="_blank" rel="noopener noreferrer">Annual Report CRVPF 2025</a><a href={reportUrls[3]} target="_blank" rel="noopener noreferrer">Annual Report CRVPF 2023</a><a href={reportUrls[9]} target="_blank" rel="noopener noreferrer">Edition 2, 2026</a></div></div><a href={reportUrls[0]} target="_blank" rel="noopener noreferrer" className="btn report-action">READ OUR 2025 ABRIDGED ANNUAL REPORT <ArrowRight size={16}/></a><small className="report-disclaimer">Source: crvpf.org/</small></div></div></section>
  <section className="section"><div className="container"><div className="newsletter"><div><div className="section-kicker">Stay connected</div><h2>Newsletter signup</h2><p>Demo signup - will connect to CRVPF Mailchimp on approval. The Outlook preview prepares a draft and sends nothing.</p><a href="mailto:info@crvpf.org?subject=CRVPF%20newsletter%20signup">Fallback: email info@crvpf.org</a></div><div><form className="form-row" onSubmit={submitNewsletter}><input className="field" type="email" aria-label="Email address" placeholder="Your email address" value={email} onChange={e=>setEmail(e.target.value)} required data-testid="input-newsletter-email"/><button className="btn btn-orange" type="submit" data-testid="button-newsletter">Join newsletter</button></form><button className="btn btn-outline" style={{marginTop:10}} type="button" onClick={()=>setNewsletterOpen(true)}>Preview Outlook email template</button></div></div></div></section>
  <section className="section tight"><div className="container"><SectionHead eyebrow="Beyond TOR - Included Free" title="Tools for partners and communities."/><div className="god-tier-grid"><Link className="soft-card" href="/donor-portal"><h3>Donor Portal</h3><p>Demo login, impact links, report access and a return-to-donate flow.</p></Link><div className="soft-card"><h3>Youth Opportunity Finder</h3><DistrictFinder notify={notify}/></div><div className="soft-card"><h3>Safeguarding Hotline</h3><SafeguardingReport notify={notify}/></div><div className="soft-card"><h3>WhatsApp + USSD concept</h3><WhatsAppSignup notify={notify}/></div><div className="soft-card"><h3>Low-network PWA</h3><p>Works on low network. This demo does not claim offline access to uncached pages.</p><Link className="arrow-link" href="/dashboard">Open dashboard <ArrowRight size={15}/></Link></div><Link className="soft-card" href="/dashboard"><h3>Board Summary</h3><p>What the Board gets in 2 mins: documented milestones, current targets, partner preview and safeguarding demo.</p></Link></div><div className="guarantee-box"><strong>Guarantee</strong><p>If homepage not live 14 Dec, Milestone 1 free. If staff cannot publish alone after training, retrain free.</p></div></div></section>
   {officeOpen&&<Modal title="Grants and Administration Office in Washington DC" onClose={()=>setOfficeOpen(false)}><p>Source: crvpf.org/about-us/</p></Modal>}
  {newsletterOpen&&<Modal title="Outlook newsletter template" onClose={()=>setNewsletterOpen(false)}><div className="template-preview"><strong>To</strong><p>info@crvpf.org</p><strong>Subject</strong><p>CRVPF newsletter signup</p><strong>Message</strong><p>Please add my email address to CRVPF newsletter updates. This demo does not submit to Mailchimp.</p></div><a className="btn btn-blue" href={`https://outlook.office.com/mail/deeplink/compose?to=info%40crvpf.org&subject=${encodeURIComponent('CRVPF newsletter signup')}&body=${encodeURIComponent('Please add my email address to CRVPF newsletter updates.')}`} target="_blank" rel="noopener noreferrer">Open in Outlook <ArrowRight size={15}/></a></Modal>}
 </main>
}
function SourcePhoto({src,alt,className}:{src:string;alt:string;className:string}){const[failed,setFailed]=useState(false);return <figure className={`local-image ${className}`}>{failed?<div className="photo-fallback" role="img" aria-label={alt}>CRVPF photo unavailable</div>:<img src={src} alt={alt} loading={className==='hero-photo'?'eager':'lazy'} decoding="async" onError={()=>setFailed(true)}/>}<figcaption>{failed?'Source: crvpf.org - photo unavailable; caption to be confirmed by CRVPF':'Photo: CRVPF / Partner Organisation'}</figcaption></figure>}
function EditionPhoto({className}:{className:string}){return <SourcePhoto src="https://crvpf.org/wp-content/uploads/2026/06/joanna-768x503.jpg" alt="CRVPF photo from the Bold Movements Edition 2, 2026 page" className={className}/>}
function AnimatedMetric({value}:{value:number}){const [shown,setShown]=useState(0);useEffect(()=>{const element=document.querySelector(`[data-metric="${value}"]`);if(!element)return;let frame=0;let observer:IntersectionObserver|undefined;const finish=()=>setShown(value);const start=()=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}const duration=400,started=performance.now();const tick=(now:number)=>{const progress=Math.min(1,(now-started)/duration);setShown(Math.round(value*(1-Math.pow(1-progress,3))));if(progress<1)frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick)};if('IntersectionObserver' in window){observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){start();observer?.disconnect()}},{threshold:.4});observer.observe(element)}else start();return()=>{observer?.disconnect();cancelAnimationFrame(frame)}},[value]);return <strong data-metric={value} aria-label={value.toLocaleString()}><span aria-hidden="true">{shown.toLocaleString()}</span></strong>}
function ProgramCard({p,i}:{p:Program;i:number}){return <article className="program-card"><span className="number">0{i+1} / {p.short}</span><h3>{p.name}</h3><p>{p.summary}</p><Link className="arrow-link" href={p.slug}>Explore programme <ArrowRight size={15}/></Link></article>}
  function StoryCard({s,i}:{s:typeof storyData[number];i:number}){const[open,setOpen]=useState(false);const citation='Source: crvpf.org';const label=s.country?`${s.program} · ${s.country}`:s.program;return <article className="story-card"><div className="story-icon">{i%2===0?<HeartHandshake size={25}/>:<Sparkles size={25}/>}</div><div><span className="tag">{label}</span><h3 style={{marginTop:12}}>{s.name}</h3><p>{s.text}</p>{s.quote&&<blockquote className="story-quote">“{s.quote}”</blockquote>}<small className="source-note">{citation}</small><button className="arrow-link story-read-more" onClick={()=>setOpen(true)}>Read More <ArrowRight size={15}/></button></div>{open&&<Modal title={s.name} onClose={()=>setOpen(false)}><span className="tag">{label}</span><p>{s.text}</p>{s.quote&&<blockquote>“{s.quote}”</blockquote>}<small className="source-note">{citation}</small><a className="btn btn-blue" href={s.href} target="_blank" rel="noopener noreferrer">Read story on CRVPF <ArrowRight size={15}/></a></Modal>}</article>}
function MapPanel({onPin,selectedCountry,timelineYear,onOffice}:{onPin:(c:string)=>void;selectedCountry?:string;timelineYear?:number;onOffice?:()=>void}){const positions=[['Uganda','35%','42%'],['Kenya','62%','50%'],['Tanzania','53%','70%'],['Ethiopia','69%','27%']];return <div className="map-panel"><div className="map-copy"><div className="eyebrow">Across East Africa</div><h2>Our Reach From 2021 - 2023</h2><p>CRVPF operates in Uganda, Kenya, Tanzania and Ethiopia.</p><div className="pin-buttons">{countries.map(c=><button id={`filter-country-${c.toLowerCase()}`} key={c} className={selectedCountry===c?'active':''} onClick={()=>onPin(c)} data-testid={`map-${c.toLowerCase()}`}>{c}</button>)}</div>{onOffice&&<button type="button" className="usa-office-pin" onClick={onOffice} data-testid="map-usa-office"><MapPin size={18}/>Grants and Administration Office in Washington DC</button>}{timelineYear&&<div className="map-year-caption"><strong>Selected timeline year: {timelineYear}</strong><span>Country locations are illustrative. No country-specific annual totals were supplied.</span><div className="map-year-rail" aria-label={`Timeline year ${timelineYear}`}><span className="map-year-dot" style={{left:`${((timelineYear-2015)/11)*100}%`}}/><span>2015</span><span>2026</span></div></div>}</div><div className="map-visual" aria-label="Illustrative map, not a geographic boundary map">{positions.map(([c,l,t])=><button key={c} className={`pin ${selectedCountry===c?'selected':''}`} style={{left:l,top:t}} aria-label={`Explore ${c}`} onClick={()=>onPin(c)} data-testid={`map-pin-${c.toLowerCase()}`}><span className="pin-label" style={{transform:'rotate(45deg)',left:12,top:-7}}>{c}</span></button>)}</div></div>}
function PageHero({eyebrow,title,description}:{eyebrow:string;title:string;description:string}){return <section className="page-hero"><div className="container"><div className="breadcrumbs"><Link href="/">Home</Link><ChevronRight size={13}/>{eyebrow}</div><div className="eyebrow">{eyebrow}</div><h1 className="page-title">{title}</h1><p>{description}</p></div></section>}
function About(){
 const clusterText='Our principles of partnership with community organizations revolve around a place-based Cluster Partnership model that brings together 2–5 community organizations in one geographic area to implement CRVPF’s interventions. This ensures clear and transparent working relationships that are inclusive and mutually beneficial, grounded in equity, respect, and shared passion. To support this collaboration, CRVPF offers a Planning and Learning Grant that enables cluster partners to build strong relationships that strengthen the management and implementation of violence against children (VAC) prevention programs. The grant provides space for partners to listen to the community, co-create relevant interventions, and conduct joint situation and power analyses. This helps ensure that the solutions are grounded in the lived experiences, challenges, and resources of the specific communities. This approach promotes programmatic synergy, enables economies of scale in capacity building and funding eligibility, and creates safe and supportive environments for children and young people.';
 const approaches=[['Cluster Partnership Model',clusterText],['Joint Program Approach',`${approachContent.joint.summary} ${approachContent.joint.activities[0]}`],['Coordinated Program Approach',`${approachContent.coordinated.summary} ${approachContent.coordinated.activities[0]}`]];
  return <main><PageHero eyebrow="About CRVPF" title="Children's Rights and Violence Prevention Fund (CRVPF)" description={CRVPF_INTRO}/><section className="section"><div className="container"><SectionHead eyebrow="" title="Vision, Mission & Goal"/><div className="content-grid"><div className="prose"><h2>Our Vision</h2><p>{CRVPF_VISION}</p><h2>Mission</h2><p>{CRVPF_MISSION}</p><h2>Goal</h2><p>{CRVPF_GOAL}</p><small className="source-note">Source: crvpf.org/</small></div><aside className="soft-card"><div className="section-kicker">Our Reach From 2021 - 2023</div><ul className="check-list"><li>1,399 Program participants</li><li>266 young people engaged in dignified and fulfilling work as entrepreneurs or formally employed.</li><li>93 parents participating in weekly savings and lending meetings to increase household incomes.</li><li>78 adolescent girls regularly attending safe space meetings across East Africa.</li></ul><small className="source-note">Source: crvpf.org/about-us/</small></aside></div><div id="approaches" style={{marginTop:65,scrollMarginTop:100}}><SectionHead eyebrow="How we work" title="Approaches"/><div className="program-grid">{approaches.map(([title,text],i)=><article className="soft-card" key={title}><span className="tag">0{i+1}</span><h3 style={{marginTop:17}}>{title}</h3><p>{text}</p><small className="source-note">Source: crvpf.org/our-approaches/</small></article>)}</div></div><div className="soft-card" style={{marginTop:34,display:'flex',gap:18,alignItems:'center'}}><div className="story-icon"><Users/></div><div><span className="section-kicker">Our Story</span><h3 style={{margin:'5px 0'}}>CRVPF is led by an East African leader and board with strong relationships and credibility among external donors.</h3><small className="source-note">Source: crvpf.org/about-us/</small></div></div><div className="soft-card history-card"><span className="section-kicker">Our Story</span><p>CRVPF was established to balance the power of funding in East African local organizations from external funders who traditionally set the agenda to a more collaborative and facilitative regional intermediary. This intermediary model emphasizes co-creating program agendas with community organizations while developing their capacity.</p><small className="source-note">Source: crvpf.org/</small></div><div className="about-studios"><ElitechStudios title="Powered by ELITECH TECHNOLOGIES - Our Studios"/></div></div></section></main>
}

const approachContent={coordinated:{title:'Coordinated Program approach for integrated holistic programs',summary:'In our mission to build power of young people to make informed decisions and access dignified, fulfilling work, CRVPF developed a coordinated approach that maximizes the skills provided by our community partners while bridging the gap between young people and the private sector particularly financial institutions, to develop financial products tailored for young people. The approach brings together CRVPFs three programs AGPP, EYDCD, and PVAC, community organizations, financial institutions, telecommunication providers for digital solutions, alternative credit facilities among others, to provide program participants with a comprehensive and integrated package of services.',activities:['Our community partners bring their unique expertise to work with the same youth in the same geographical areas, offering life skills training, parenting skills training, and inclusive financial education. By leveraging on the strength of each program, the coordinated approach aims to create an enabling environment for young people to thrive in a safe environment free from violence and sexual violence.'],partnerships:['Community organizations','Financial institutions','Telecommunication providers','Private sector'],resources:[]},joint:{title:'Joint Program Approach',summary:'Initially, CRVPF’s programs, the Prevention of Violence against Children (PVAC) and the Adolescent Girls’ Power Program (AGPP), supported partners in different locations. Even when partners operated within the same geographical area, there was no intentional or strategic coordination between them. Recognizing the unique strengths of each program in addressing violence and sexual violence against children and young people, CRVPF adopted a Joint Program Approach. By integrating the two programs within the same geographical area, the initiative aims to enhance partner interventions for greater impact.',activities:['In this collaborative model, PVAC contributes expertise in strengthening parenting skills and spousal relationships, reducing family economic stress through Village Savings and Loan Associations (VSLAs), and fostering an enabling school environment where young people can thrive. Meanwhile, AGPP brings its experience in building power for adolescent girls and transforming structural barriers that limit their choices and agency, using its life skills manual as a key tool.'],partnerships:['PVAC and AGPP partners in the same geographical area'],resources:[]}};
function ProgrammeDetail({slug,notify}:{slug:string;notify:(s:string)=>void}){
 const order=['/programmes/pvac','/programmes/agpp','/programmes/eydcd','/programmes/coordinated','/programmes/joint'];
 const index=order.indexOf(slug);
 const p=programs.find(x=>x.slug===slug);
 const approach=slug.endsWith('coordinated')?approachContent.coordinated:slug.endsWith('joint')?approachContent.joint:undefined;
 const short=p?.short||(slug.endsWith('coordinated')?'Coordinated':'Joint');
 const title=p?.name||approach?.title||'Programme';
 const summary=p?.summary||approach?.summary||'';
 const activities=p?.details||approach?.activities||[];
 const stories=p?storyData.filter(s=>s.program===p.short):[];
  const resources=p?.short==='PVAC'?[{title:'PVAC Program Profile',url:'https://crvpf.org/wp-content/uploads/2025/03/PVAC-Program-Profile.pdf'},{title:'Parenting for Respectability Module One: Bonding and attachment',url:'https://crvpf.org/wp-content/uploads/2025/03/MODULE-ONE_Bonding-and-attachment.pdf'},{title:'Parenting for Respectability Module 2',url:'https://crvpf.org/wp-content/uploads/2025/03/Parenting-for-Respectability-Module-2.pdf'},{title:'Parenting for Respectability Module 3',url:'https://crvpf.org/wp-content/uploads/2025/03/Parenting-for-Respectability-Module-3.pdf'},{title:'Parenting for Respectability Module 4',url:'https://crvpf.org/wp-content/uploads/2025/03/Parenting-for-Respectability-Module-4.pdf'},{title:'Parenting for Respectability Module 5',url:'https://crvpf.org/wp-content/uploads/2025/03/Parenting-for-Respectability-Module-5.pdf'}]:p?.short==='AGPP'?[{title:'AGPP Program Profile',url:'https://crvpf.org/wp-content/uploads/2025/03/AGPP-Program-Profile.pdf'},{title:'This Little Light of Mine · Module 1',url:'https://crvpf.org/wp-content/uploads/2025/03/ThisLittleLightofMine_Module1.pdf'},{title:'This Little Light of Mine · Module 2',url:'https://crvpf.org/wp-content/uploads/2025/03/ThisLittleLightofMine_Module2.pdf'},{title:'This Little Light of Mine · Module 3',url:'https://crvpf.org/wp-content/uploads/2025/03/ThisLittleLightofMine_Module3.pdf'},{title:'This Little Light of Mine · Module 4',url:'https://crvpf.org/wp-content/uploads/2025/03/ThisLittleLightofMine_Module4.pdf'},{title:'This Little Light of Mine · Module 5',url:'https://crvpf.org/wp-content/uploads/2025/03/5ThisLittleLightofMine_Module5.pdf'}]:p?.short==='EYDCD'?[{title:'EYDCD Program Profile',url:'https://crvpf.org/wp-content/uploads/2025/03/EYDCD-1.pdf'},{title:'EYDCD program page',url:'https://crvpf.org/empowering-youth-through-data-and-community-development-program/'}]:approach?[{title:'CRVPF approaches',url:'https://crvpf.org/our-approaches/'}]:[];
  const partnerships=p?.short==='EYDCD'?['Children’s Rights and Violence Prevention Fund (CVRPF)','gnuGrid CRB','Mastercard Foundation']:p?.short==='AGPP'?['KIWOHEDE','CRVPF community partners']:p?.short==='PVAC'?['Community organizations']:approach?.partnerships||[];
 const previous=index===0?'/#programmes':order[index-1];
 const next=index===order.length-1?'/#programmes':order[index+1];
 const previousLabel=index===0?'Back to Programmes':`Previous: ${order[index-1].split('/').pop()?.toUpperCase()}`;
 const nextLabel=index===order.length-1?'Programme list':`Next: ${order[index+1].split('/').pop()?.toUpperCase()}`;
  const achievements=p?.short==='PVAC'?['Source: crvpf.org/our-programs/']:p?.short==='AGPP'?['10 Safe Spaces Established','+440 Adolescent Girls trained in life skills using This Little Light of Mine Manual.','+534 Adolescent Girls & Young Mothers regularly attending safe space meetings across East Africa','+388 Trained in Vocational and income generating skills','31 Children Aged 0 to 3 years registered under ECD']:p?.short==='EYDCD'?['400,000 young people (70% female)','250,000 dignified and fulfilling employment opportunities','200 community organizations','3,000 youth-led Village Savings and Loan Associations (VSLAs)']:['As per crvpf.org/our-approaches/'];
  return <main><PageHero eyebrow={short} title={title} description={summary}/><section className="section"><div className="container"><div className="programme-summary-grid"><section className="soft-card"><h2>Objectives</h2><p>{summary}</p></section><section className="soft-card"><h2>Coverage</h2><p>CRVPF operates in Uganda, Kenya, Tanzania and Ethiopia.</p></section></div><div className="content-grid programme-content"><div><section className="soft-card"><h2>Activities</h2><ul className="check-list">{activities.map(item=><li key={item}>{item}</li>)}</ul></section><section className="soft-card"><h2>Achievements and targets</h2><ul className="check-list">{achievements.map(item=><li key={item}>{item}</li>)}</ul></section><section className="soft-card"><h2>Partnerships</h2><ul className="check-list">{partnerships.map(item=><li key={item}>{item}</li>)}</ul></section></div><aside><section className="soft-card"><h2>Stories</h2>{stories.length?stories.map(s=><div className="programme-story" key={s.name}><span className="tag">{s.country?`${s.program} · ${s.country}`:s.program}</span><h3>{s.name}</h3><p>{s.text}</p><small className="source-note"><a href={s.href} target="_blank" rel="noopener noreferrer">Source: crvpf.org</a></small><a href={s.href} target="_blank" rel="noopener noreferrer" className="arrow-link">Read story on CRVPF <ArrowRight size={14}/></a></div>):<p>As per crvpf.org.</p>}</section><section className="soft-card" style={{marginTop:16}}><h2>Resources</h2>{resources.map(item=><div className="resource-row" key={item.url}><span>{item.title}</span><a className="btn btn-outline" href={item.url} target="_blank" rel="noopener noreferrer">Open resource</a></div>)}<Link className="arrow-link" href="/publications">Open publication archive <ArrowRight size={14}/></Link></section></aside></div><div className="programme-pager"><Link className="btn btn-outline" href={previous}>← {previousLabel}</Link><Link className="btn btn-blue" href={next}>{nextLabel} →</Link></div>{short==='EYDCD'&&<section className="soft-card district-panel"><h2>District Finder</h2><p>District-specific partner, opportunity, and VSLA details are not listed in the EYDCD source page.</p><DistrictFinder notify={notify}/></section>}</div></section></main>
}

function Impact({country,setCountry,program,setProgram}:{country:string;setCountry:(s:string)=>void;program:string;setProgram:(s:string)=>void}){useEffect(()=>{const match=window.location.hash.match(/^#filter-country-(uganda|kenya|tanzania|ethiopia)$/i);if(match){const selected=countries.find(c=>c.toLowerCase()===match[1].toLowerCase());if(selected)setCountry(selected)}},[setCountry]);const filtered=storyData.filter(s=>(country==='All'||s.country===country)&&(program==='All'||s.program===program));return <main><PageHero eyebrow="Impact" title="Our Reach From 2021 - 2023" description="CRVPF operates in Uganda, Kenya, Tanzania and Ethiopia."/><section className="section"><div className="container"><div className="filter-toolbar"><div><strong>Country</strong><div className="pill-row">{['All',...countries].map(v=><button id={`filter-country-${v.toLowerCase()}`} className={`pill ${country===v?'selected':''}`} key={v} onClick={()=>setCountry(v)} data-testid={`filter-country-${v.toLowerCase()}`}>{v}</button>)}</div></div><div><strong>Programme</strong><div className="pill-row">{programmeFilters.map(v=><button className={`pill ${program===v?'selected':''}`} key={v} onClick={()=>setProgram(v)} data-testid={`filter-program-${v.toLowerCase()}`}>{v}</button>)}</div></div></div><p className="showing-count" role="status">Showing {filtered.length} stories</p>{filtered.length?<div className="impact-grid">{filtered.map((s,i)=><article className="impact-card" id={`story-${s.name.toLowerCase().replaceAll(' ','-')}`} key={s.name}><span className="tag">{s.country?`${s.country} · ${s.program}`:s.program}</span><h2>{s.name}</h2><p>{s.text}</p>{s.quote&&<blockquote className="story-quote">“{s.quote}”</blockquote>}<small className="source-note"><a href={s.href} target="_blank" rel="noopener noreferrer">Source: crvpf.org</a></small><span className="tag">{i+1} / {filtered.length}</span></article>)}</div>:<div className="empty-state">No stories found</div>}</div></section></main>}
function Annual({notify}:{notify:(s:string)=>void}){
 const[email,setEmail]=useState(''),[name,setName]=useState(''),[copies,setCopies]=useState('1'),[delivery,setDelivery]=useState('Kampala');
 const printQuote=(e:FormEvent)=>{e.preventDefault();notify('Demo quote request only; no order was sent.')};
 const chapters=[
  ['Bold Movements','As we celebrate 10 years of impact, CRVPF is proud to present a rich collection of stories highlighting the lived experiences of our partners, the communities they support, and our shared journey.'],
  ['Annual Report CRVPF 2025','Annual Report CRVPF 2025'],
  ['Bold Threads & Bolder Futures: Inside the Pakasa Fashion Show','Led by Joanita (Joanna) Nabagesera, founder and CEO of Lulungi Couture and an alumna of the Empowering Youth Through Data and Community Development (EYDCD) program implemented by CRVPF, gnuGrid CRB and community partners, with support from Mastercard Foundation.'],
  ['She Found Her Voice and Began Helping Others Find Theirs: Doreen’s Story','Through the Safe Space intervention under CRVPF’s Adolescent Girls Power Program (AGPP), Doreen learned hairdressing, snack making, flower weaving, marketing, saving, and leadership skills alongside other girls and young mothers.'],
  ['Fathers Believe Other Fathers: Juma’s Story','Through the Father on Duty movement under CRVPF’s Prevention of Violence against Children and Young People (PVAC) program, fathers gather in spaces where men speak openly with other men about parenting, relationships, pressure, anger, and responsibility.'],
  ['Priscilla Kirabo','EYDCD Youth Representative Priscilla Kirabo encouraged young people to use digital tools strategically to generate income and build livelihoods.']
 ];
 return <main><PageHero eyebrow="Annual Reports" title="Annual Report CRVPF 2025" description="Source: crvpf.org/knowledge-hub-2/"/><section className="section"><div className="container"><div className="annual-intro"><div><span className="section-kicker">BOLD MOVEMENTS — Celebrating 10 years of impact!</span><h2>Welcome to Bold Movements!</h2><p>Across communities in Uganda, Kenya, Tanzania, and Ethiopia, young people, parents, mentors, and community leaders are creating change in ways that are bold, practical, and deeply human.</p><small className="source-note"><a href="https://crvpf.org/bold-movements/" target="_blank" rel="noopener noreferrer">Source: crvpf.org/bold-movements/</a></small></div><EditionPhoto className="annual-photo"/></div><div className="annual-chapters">{chapters.map(([title,text],i)=><article className="annual-chapter" key={title}><span>{title}</span><p>{text}</p><small className="source-note">Source: crvpf.org</small>{i===1&&<a className="arrow-link" href={reportUrls[1]} target="_blank" rel="noopener noreferrer">Open Annual Report CRVPF 2025 <ArrowRight size={14}/></a>}</article>)}</div><section className="annual-chart-card"><h2>Our Reach From 2021 - 2023</h2><div className="annual-bars"><div className="annual-bar-row"><span>Program participants</span><div><i style={{width:'100%'}}/></div><strong>1,330</strong></div><div className="annual-bar-row"><span>Young people engaged in dignified and fulfilling work</span><div><i style={{width:'19%'}}/></div><strong>253</strong></div><div className="annual-bar-row"><span>Parents participating in weekly savings and lending meetings</span><div><i style={{width:'7%'}}/></div><strong>88</strong></div><div className="annual-bar-row"><span>Adolescent girls regularly attending safe space meetings</span><div><i style={{width:'6%'}}/></div><strong>74</strong></div></div><small className="source-note">Source: crvpf.org/</small></section><div className="annual-quote-grid"><blockquote>“Just because you are a teen mother does not mean your life is over. You can still achieve your dreams and become someone in life.” — Doreen<small className="source-note">Source: crvpf.org/edition-2-2026/</small></blockquote><blockquote>“Father on Duty taught me that being a man means caring, listening, and protecting my family without violence.” — Juma<small className="source-note">Source: crvpf.org/edition-2-2026/</small></blockquote></div><section className="soft-card annual-actions"><h2>Download and share</h2><a className="btn btn-blue" href={reportUrls[1]} target="_blank" rel="noopener noreferrer">Download Annual Report CRVPF 2025</a><button className="btn btn-outline" onClick={async()=>{try{await navigator.clipboard.writeText(reportUrls[1]);notify('Annual Report CRVPF 2025 link copied.')}catch{notify('Copy is unavailable in this browser.')}}}>Copy report link</button><a className="btn btn-outline" href={`mailto:info@crvpf.org?subject=${encodeURIComponent('Annual Report CRVPF 2025')}&body=${encodeURIComponent(reportUrls[1])}`}>Share by email</a></section><section className="social-cards"><article className="soft-card"><strong>Share the report</strong><p>Annual Report CRVPF 2025</p><button className="btn btn-outline" onClick={async()=>{try{if(navigator.share){await navigator.share({title:'Annual Report CRVPF 2025',url:reportUrls[1]})}else notify('Device sharing is not available here. Use Copy report link.')}catch{notify('Sharing was cancelled or is unavailable.')}}}>Share</button></article><article className="soft-card"><strong>Printed-copy quote · demo</strong><p>This demo does not submit a print order.</p><form className="form-stack" onSubmit={printQuote}><label>Name<input className="field" value={name} onChange={e=>setName(e.target.value)} required minLength={2}/></label><label>Copies<input className="field" type="number" min="1" max="100" value={copies} onChange={e=>setCopies(e.target.value)} required/></label><label>Delivery<select className="field" value={delivery} onChange={e=>setDelivery(e.target.value)}><option>Kampala</option><option>Upcountry</option></select></label><button className="btn btn-orange" type="submit">Get Quote</button></form></article></section><section className="newsletter annual-newsletter" id="newsletter"><div><div className="section-kicker">Newsletter</div><h2>Get CRVPF updates</h2><p>Demo signup - will connect to CRVPF Mailchimp on approval.</p><a href="mailto:info@crvpf.org?subject=CRVPF%20newsletter%20signup">Fallback: email info@crvpf.org</a></div><form className="form-stack" onSubmit={e=>{e.preventDefault();if(email.includes('@'))notify('Demo signup - will connect to CRVPF Mailchimp on approval.')}}><label>Email<input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><button className="btn btn-blue" type="submit">Join newsletter</button><Link href="/#newsletter" className="arrow-link">Outlook template preview on home page</Link></form></section></div></section></main>
}

function Dashboard({year,setYear,country,setCountry,notify}:{year:number;setYear:(y:number)=>void;country:string;setCountry:(c:string)=>void;notify:(s:string)=>void}){
 const[tab,setTab]=useState('Audit'),period=year>=2021&&year<=2023,years=Array.from({length:12},(_,i)=>2015+i);
 const milestone=period?'CRVPF publishes aggregate results for 2021–2023; it does not publish a breakdown for this selected year.':'No year-specific result was supplied for this year.';
 const partners=[['Sanyu Centre for Arts and Rights (SARI)','Named in Beatrice’s story']];
 return <main><PageHero eyebrow="Interactive dashboard · demo" title="Impact overview" description="Published CRVPF figures for 2021–2023; this demo does not show live data."/><section className="section"><div className="container"><div className="dashboard-stats"><article><span>Program participants · 2021–2023</span><strong>1,330</strong></article><article><span>Young people engaged in dignified and fulfilling work</span><strong>253</strong></article><article><span>Parents participating in weekly savings and lending meetings</span><strong>88</strong></article></div><small className="source-note">Source: crvpf.org/</small><label className="year-slider-label" htmlFor="year-slider">Year: {year} · 2015–2026</label><input id="year-slider" className="year-control" type="range" min="2015" max="2026" value={year} onChange={e=>setYear(Number(e.target.value))} data-testid="slider-year"/><div className="dashboard-layout"><div className="dashboard-main"><MapPanel onPin={setCountry} selectedCountry={country} timelineYear={year}/><div className="soft-card dashboard-chart-card"><h2>Published Results · 2021–2023</h2><p>{milestone} No annual values are inferred.</p><div className="timeline-chart" aria-label={`Timeline from 2015 to 2026, selected ${year}; program period values only`}>{years.map(y=><button key={y} type="button" className={`timeline-year ${y===year?'selected':''} ${period&&y>=2021&&y<=2023?'documented':''}`} onClick={()=>setYear(y)} aria-label={`Select ${y}`}><span>{y}</span></button>)}</div><div className="chart-period-values"><div><strong>1,330</strong><span>Program participants, 2021–2023</span></div><div><strong>253</strong><span>Young people engaged in dignified and fulfilling work</span></div><div><strong>88</strong><span>Parents in weekly savings and lending meetings</span></div><div><strong>74</strong><span>Adolescent girls at safe space meetings</span></div></div><small className="source-note">Source: crvpf.org · period totals only, not annual series</small></div><div className="dashboard-cms-card soft-card"><h2>Safeguarding-First CMS Panel</h2><ul className="check-list"><li>Consent signed</li><li>No full name</li><li>No school or exact location</li><li>Communications approved</li></ul><Link className="btn btn-orange" href="/admin-demo">Open Safeguarding CMS</Link></div></div><aside className="dashboard-side"><section className="soft-card"><h2>Partner Portal Preview</h2><span className="tag">DEMO · NOT LIVE</span>{partners.map(([name,status])=><div className="partner-preview-row" key={name}><strong>{name}</strong><span>{status}</span></div>)}<small className="source-note">The CRVPF source names SARI in Beatrice’s story; it does not publish grant statuses or partner account records.</small><Link href="/partners" className="arrow-link">Open Partner Portal <ArrowRight size={14}/></Link></section><section className="soft-card board-summary"><h2>Board Summary</h2><p>Published programme-period results, safeguarding demo status and country map.</p><button className="btn btn-outline" onClick={()=>window.print()}>Print summary</button></section></aside></div><section className="soft-card dashboard-tabs-card"><div className="tabs" role="tablist">{['Audit','Analytics','Hosting','Training'].map(t=><button role="tab" aria-selected={tab===t} className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div><DashboardTab tab={tab} notify={notify}/></section><div className="dashboard-mobile-links"><Link className="soft-card" href="/admin-demo">Safeguarding CMS <ArrowRight size={14}/></Link><Link className="soft-card" href="/partners">Partner Portal <ArrowRight size={14}/></Link></div></div></section></main>
}
function Partners({tab,setTab,login,setLogin,notify}:{tab:string;setTab:(s:string)=>void;login:boolean;setLogin:(b:boolean)=>void;notify:(s:string)=>void}){
 const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');
 const tabs=['My Grants','Reports Due','My Stories','Messages'];
 const sign=(e:FormEvent)=>{e.preventDefault();if(email==='demo@crvpf.org'&&password==='demo123'){setLogin(true);setError('');notify('Partner demo dashboard opened.')}else setError('Invalid demo credentials. Use demo@crvpf.org / demo123')};
 return <main><PageHero eyebrow="Partner portal" title="Partner workspace" description="A local demo account shows source information only; it is not connected to live partner data."/><section className="section"><div className="container">{!login?<div className="content-grid"><div className="soft-card"><h2>Sign in to the demo</h2><p>Demo email: demo@crvpf.org · Password: demo123</p><div className="notice">This demo has no external account service. In final WordPress, Partner role sees only own grants.</div></div><form className="soft-card form-stack" onSubmit={sign}><label>Email<input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username" required/></label><label>Password<input className="field" type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></label>{error&&<div className="error-box" role="alert">{error}</div>}<button className="btn btn-green" type="submit">Sign in</button></form></div>:<div className="soft-card"><div className="portal-heading"><div><span className="section-kicker">Demo partner · Sanyu Centre for Arts and Rights (SARI)</span><h2>Partner Portal</h2></div><button className="btn btn-outline" onClick={()=>setLogin(false)}>Sign out</button></div><div className="notice">Demo partner view only. No live account, grant, report, message, or access-control service is connected. In final WordPress, Partner role sees only own grants.</div><div className="tabs" style={{marginTop:24}} role="tablist">{tabs.map(t=><button role="tab" aria-selected={tab===t} className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="portal-tab-panel"><h3>{tab}</h3>{tab==='My Grants'?<article className="result-card"><strong>Sanyu Centre for Arts and Rights (SARI)</strong><p>As per crvpf.org.</p><a href="https://crvpf.org/baskets-bonds-and-bold-women-a-story-of-sisterhood-and-strength/" target="_blank" rel="noopener noreferrer">Source story</a></article>:tab==='Reports Due'?<article className="result-card"><strong>Reports Due</strong><p>As per crvpf.org.</p><a href="https://crvpf.org/knowledge-hub-2/" target="_blank" rel="noopener noreferrer">Open CRVPF Knowledge Hub</a></article>:tab==='My Stories'?<article className="result-card"><strong>Beatrice · story reference</strong><p>Sanyu Centre for Arts and Rights (SARI), One Voice Savings Group, and Kyisa Kya Maria Arts and Crafts Group are named in the story.</p><a href="https://crvpf.org/baskets-bonds-and-bold-women-a-story-of-sisterhood-and-strength/" target="_blank" rel="noopener noreferrer">Read the story on CRVPF</a></article>:<article className="result-card"><strong>Messages</strong><p>No live messages are connected. For a real enquiry, email <a href="mailto:info@crvpf.org">info@crvpf.org</a>.</p></article>}</div></div>}</div></section></main>
}
function Admin({items,onPublish,notify}:{items:AdminStory[];onPublish:(s:AdminStory)=>void;notify:(s:string)=>void}){
 const[title,setTitle]=useState(''),[country,setCountry]=useState(''),[programme,setProgramme]=useState(''),[story,setStory]=useState(''),[photo,setPhoto]=useState(''),[anonymous,setAnonymous]=useState(false),[checks,setChecks]=useState([false,false,false,false]),[gateWarning,setGateWarning]=useState(false);
 const[drafts,setDrafts]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('crvpf-newsletter-drafts')||'[]')}catch{return[]}});
 const ready=checks.every(Boolean);
 const updateCheck=(index:number,value:boolean)=>{const next=checks.map((item,i)=>i===index?value:item);setChecks(next);if(next.every(Boolean))setGateWarning(false)};
 const warnGate=()=>{if(!ready){setGateWarning(true);notify('Safeguarding gate: Complete all 4 checks.')}};
 const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!ready){warnGate();return}const audit='Published by Demo User, Approved by Communications, 13 Nov 2026, 15:42';onPublish({id:`story-${Date.now()}`,title:title.trim(),country,programme,story:story.trim(),status:'Published',anonymous,audit});e.currentTarget.reset();setTitle('');setCountry('');setProgramme('');setStory('');setPhoto('');setAnonymous(false);setChecks([false,false,false,false]);setGateWarning(false);notify('Story published to this browser’s Published Stories list.')};
 const generateDraft=()=>{const draft='CRVPF advances the safety and rights of children and young people by working with community organizations through cluster partnerships. This draft uses supplied CRVPF text and requires Communications approval.';const next=[draft,...drafts];setDrafts(next);localStorage.setItem('crvpf-newsletter-drafts',JSON.stringify(next));notify('Newsletter draft added to the Communications Review queue.')};
 return <main><PageHero eyebrow="Safeguarding CMS · demo" title="Publish a story in 2 minutes - no code" description="Local demo workflow: Draft → Communications Review → Approved → Published."/><section className="section"><div className="container"><div className="cms-workflow" aria-label="Draft to published workflow">{['Draft','Communications Review','Approved','Published'].map((step,i)=><span key={step}>{i>0&&<b>→</b>}{step}</span>)}</div><div className="content-grid cms-layout"><form className="soft-card form-stack" onSubmit={submit}><h2>Story draft</h2><label>Title<input className="field" value={title} onChange={e=>setTitle(e.target.value)} required minLength={3}/></label><label>Country<select className="field" value={country} onChange={e=>setCountry(e.target.value)} required><option value="">Select country</option>{countries.map(c=><option key={c}>{c}</option>)}</select></label><label>Programme<select className="field" value={programme} onChange={e=>setProgramme(e.target.value)} required><option value="">Select programme</option>{programmeFilters.slice(1).map(c=><option key={c}>{c}</option>)}</select></label><label>Story text<textarea className="field" rows={6} value={story} onChange={e=>setStory(e.target.value)} required minLength={10}/></label><label>Photo placeholder<input className="field" type="file" accept="image/*" onChange={e=>setPhoto(e.target.files?.[0]?.name||'')}/></label>{photo&&<div className="notice">Selected locally: {photo}. It will not be uploaded in this demo.</div>}<div className="safeguarding-checks"><strong>Safeguarding · all four checks required</strong>{['Consent signed','No full name for under-18','No school/exact location','Communications approved'].map((item,i)=><label className="check-row" key={item}><input type="checkbox" checked={checks[i]} onChange={e=>updateCheck(i,e.target.checked)}/>{item}</label>)}</div><label className="check-row"><input type="checkbox" checked={anonymous} onChange={e=>setAnonymous(e.target.checked)}/>Keep author anonymous in the preview</label><div className="cms-publish-button-wrap" onClick={warnGate}><button disabled={!ready} className="btn btn-orange cms-publish-button" type="submit" data-testid="button-cms-publish">Publish <ArrowRight size={16}/></button></div>{gateWarning&&<div className="safeguarding-warning" role="alert">Safeguarding gate: Complete all 4 checks.</div>}<small className="notice">Publish remains disabled until all four safeguarding checks are complete. Required story fields are also validated before publishing. Do not include sensitive locations.</small></form><aside className="cms-side"><section className="soft-card"><h2>Published Stories</h2>{items.length?items.map(item=><article className="published-story" key={item.id}><span className="tag">{item.country} · {item.programme} · {item.status}</span><h3>{item.title}</h3><p>{item.story}</p>{item.status==='Published'&&<><small>Author: {item.anonymous?'Anonymous':'Not supplied'}</small><p className="audit-log">{item.audit||'Published by Demo User, Approved by Communications, 13 Nov 2026, 15:42'}</p></>}</article>):<div className="empty-state">Published stories added in this browser appear here.</div>}</section><section className="soft-card"><h2>Auto Content Studio · demo</h2><p>Generate a newsletter draft from supplied CRVPF text. It is not sent automatically.</p><button className="btn btn-green" type="button" onClick={generateDraft}>Generate Draft with Auto Content Studio</button><strong className="draft-only-label">Draft only - requires Communications approval before sending via Mailchimp.</strong><h3>Review queue</h3>{drafts.map((draft,i)=><div className="result-card" key={`${i}-${draft.slice(0,10)}`}><span className="tag">Communications Review</span><p>{draft}</p></div>)}{!drafts.length&&<div className="empty-state">Generated drafts appear here for review.</div>}</section></aside></div></div></section></main>
}
function Publications(){const[q,setQ]=useState(''),[filter,setFilter]=useState('All');const events=[{title:'Bold Threads & Bolder Futures: Inside the Pakasa Fashion Show',type:'Event',description:'The Pakasa Art and Fashion Showcase was held in celebration of International Women’s Day 2026.',href:'https://crvpf.org/edition-2-2026/'}];const entries=[...storyData.map(s=>({title:s.name,type:'Story',description:s.text,href:s.href})),...reportItems.map((title,i)=>({title,type:'Publication',description:title,href:reportUrls[i]})),...events];const types=['All','Story','Publication','Newsletter','Event','Video'];const filtered=entries.filter(e=>(filter==='All'||e.type===filter)&&(q.trim()===''||`${e.title} ${e.description}`.toLowerCase().includes(q.trim().toLowerCase())));return <main><PageHero eyebrow="Resources" title="Knowledge Hub" description="Welcome to our Knowledge Hub, a dedicated space where you can explore valuable resources that inform and inspire."/><section className="section"><div className="container"><div className="archive-controls"><label>Search archive<input className="field" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search stories, publications, events…" data-testid="input-archive-search"/></label><div className="pill-row">{types.map(t=><button key={t} className={`pill ${filter===t?'selected':''}`} onClick={()=>setFilter(t)}>{t==='Story'?'Stories':t==='Publication'?'Publications':t==='Event'?'Events':t==='Video'?'Videos':t==='Newsletter'?'Newsletters':t}</button>)}</div></div><p className="showing-count">{filtered.length} results</p>{filtered.length?<div className="archive-grid">{filtered.map(entry=><article className="archive-card" id={entry.type==='Publication'?`publication-${reportItems.indexOf(entry.title)}`:undefined} key={`${entry.type}-${entry.title}`}><span className="tag">{entry.type}</span><h2>{entry.title}</h2><p>{entry.description}</p><a className="btn btn-outline" href={entry.href} target="_blank" rel="noopener noreferrer">{entry.type==='Publication'?'Download':'Read on CRVPF'}</a></article>)}</div>:<div className="empty-state">{filter==='All'?'No archive items match your search.':`No ${filter.toLowerCase()} entries were found.`}</div>}<p className="notice" style={{marginTop:24}}>Newsletter and video records are not listed in the current source pages.</p><a className="arrow-link" href="https://crvpf.org/knowledge-hub-2/" target="_blank" rel="noopener noreferrer">Open CRVPF Knowledge Hub <ArrowRight size={14}/></a></div></section></main>}
function LowNetworkBanner(){const[online,setOnline]=useState(typeof navigator==='undefined'?true:navigator.onLine);useEffect(()=>{const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)}},[]);return <div className="low-network-banner" role="status">{online?'Works on low network · system fonts and lazy-loaded CRVPF photos':'Offline · cached app shell may load; remote CRVPF photos need a connection'}</div>}
function ElitechStudios({title}:{title:string}){const studios=[['Diglo Ventures','Web + Systems Studio','https://diglo-ventures.replit.app'],['Brimas Media','Photography, Video, Storytelling','https://brimasmedia.co'],['Print Garage','Print, Annual Report, Banners','https://printgarage.online'],['Auto Content Studio','Content Automation, Newsletters, Mailchimp Drafts','https://autocontentstudio.site']];return <section className="elitech-studios"><h2>{title}</h2><div className="elitech-grid">{studios.map(([name,description,url])=><article className="elitech-card" key={name}><strong>{name}</strong><span>{description}</span><a href={url} target="_blank" rel="noopener noreferrer">Visit Site →</a></article>)}</div></section>}
function DistrictFinder({notify}:{notify:(s:string)=>void}){const[district,setDistrict]=useState('');return <div className="district-finder"><label htmlFor="district-search">Type district<input id="district-search" className="field" value={district} onChange={e=>setDistrict(e.target.value)} placeholder="Enter a district" data-testid="input-district"/></label>{district.trim()&&<div className="district-result" aria-live="polite"><strong>Programme information for {district.trim()}</strong><p><b>Partner:</b> District-specific partner information is not present in the supplied CRVPF pages.</p><p><b>Opportunity:</b> District-specific opportunity information is not present in the supplied CRVPF pages.</p><p><b>Training:</b> District-specific training information is not present in the supplied CRVPF pages.</p><p><b>VSLA:</b> District-specific VSLA information is not present in the supplied CRVPF pages.</p><small className="source-note">Source: crvpf.org - to be confirmed by CRVPF</small><a className="btn btn-green" href={`https://wa.me/256393216519?text=${encodeURIComponent(`I would like to learn about youth opportunities in ${district.trim()}.`)}`} target="_blank" rel="noopener noreferrer">Ask about this district on WhatsApp</a><button className="btn btn-outline" onClick={()=>notify('District-specific partner and opportunity records were not supplied.')}>Data details</button></div>}</div>}
function SafeguardingReport({notify}:{notify:(s:string)=>void}){const[open,setOpen]=useState(false),[anonymous,setAnonymous]=useState(true),[details,setDetails]=useState('');const submit=(e:FormEvent)=>{e.preventDefault();if(details.trim().length<10){notify('Add a short description of the concern.');return}setOpen(false);setDetails('');notify(`Demo only: this ${anonymous?'anonymous ':''}concern was not sent. Contact info@crvpf.org or (+256) 393 216 519 for a real enquiry.`)};return <><button className="btn btn-orange" onClick={()=>setOpen(true)}>One-tap Report Concern</button>{open&&<Modal title="Report a concern" onClose={()=>setOpen(false)}><p>Do not include a child’s full name, school, or exact location. This local demo does not send or store a report.</p><form className="form-stack" onSubmit={submit}><label className="check-row"><input type="checkbox" checked={anonymous} onChange={e=>setAnonymous(e.target.checked)}/>Submit anonymously</label><label>Concern<textarea className="field" rows={5} value={details} onChange={e=>setDetails(e.target.value)} minLength={10} required/></label><button className="btn btn-orange" type="submit">Submit demo report</button></form></Modal>}</>}
function WhatsAppSignup({notify}:{notify:(s:string)=>void}){const[number,setNumber]=useState('');return <div className="whatsapp-signup"><form className="form-stack" onSubmit={e=>{e.preventDefault();notify('WhatsApp signup is a local demo; no number was stored or subscribed.');setNumber('')}}><label>WhatsApp number<input className="field" value={number} onChange={e=>setNumber(e.target.value)} type="tel" required minLength={6}/></label><button className="btn btn-green" type="submit">Preview signup</button></form><button className="btn btn-outline" onClick={()=>notify('USSD *384* is a concept only; it is not an active short code.')}>USSD *384* concept</button></div>}
function DashboardTab({tab,notify}:{tab:string;notify:(s:string)=>void}){const[tested,setTested]=useState(false);if(tab==='Audit')return <div className="dashboard-tab-content"><h3>WordPress audit checklist</h3><ul className="check-list">{['Security','Backups','Performance','SEO','Accessibility','i3C hosting'].map(x=><li key={x}>{x} · details to be confirmed in the live WordPress installation</li>)}</ul></div>;if(tab==='Analytics')return <div className="dashboard-tab-content"><h3>Analytics</h3><div className="analytics-preview">{['Page views','Top stories','Signups'].map(x=><article key={x}><strong>{x}</strong><span>Analytics data not connected</span></article>)}</div></div>;if(tab==='Hosting')return <div className="dashboard-tab-content"><h3>Hosting comparison</h3><div className="table-scroll"><table><thead><tr><th>Item</th><th>i3C hosting</th><th>Alternative</th></tr></thead><tbody>{['Hosting status','Performance details','Support details','Price'].map(x=><tr key={x}><td>{x}</td><td>To confirm</td><td>Not supplied</td></tr>)}</tbody></table></div></div>;return <div className="dashboard-tab-content"><h3>Training</h3><p>Publish in 2 mins · use the SOP and run the test.</p><Link className="arrow-link" href="/training">Open Training Hub <ArrowRight size={14}/></Link><button className="btn btn-green" onClick={()=>{setTested(true);notify('Training test checklist opened.')}}>Test</button>{tested&&<p role="status">Test ready: complete one story, one newsletter and one event on the Training Hub.</p>}</div>}
function Training({notify}:{notify:(s:string)=>void}){const[done,setDone]=useState([false,false,false]);const steps=['Publish 1 story alone','Publish 1 newsletter alone','Publish 1 event alone'];return <main><PageHero eyebrow="Training Hub" title="Publish in 2 mins" description="Staff must demonstrate each task alone before training is signed off."/><section className="section"><div className="container content-grid"><div className="soft-card"><h2>Standard operating procedures</h2><ol className="numbered-list"><li>Draft the story, newsletter or event using the supplied content.</li><li>Complete all four safeguarding checks for stories.</li><li>Send the item through Communications Review.</li><li>Publish only after communications approval.</li></ol><Link className="btn btn-green" href="/admin-demo">Open publishing practice</Link></div><div className="soft-card"><h2>Staff demonstration checklist</h2>{steps.map((s,i)=><label className="check-row" key={s}><input type="checkbox" checked={done[i]} onChange={e=>setDone(done.map((x,j)=>j===i?e.target.checked:x))}/>{s}</label>)}<button className="btn btn-blue" onClick={()=>notify(done.every(Boolean)?'Training demonstration complete.':'Complete all three solo publishing tests first.')}>Test training completion</button><p>{done.filter(Boolean).length} of 3 demonstrations checked.</p></div></div></section></main>}
function Handover({notify}:{notify:(s:string)=>void}){const[checks,setChecks]=useState([false,false,false,false]);const items=['Admin access reviewed','Staff training completed','Backup location confirmed','Monthly report reviewed'];const backup='Before updates: take a full backup of WordPress files and database; store it separately; record the date; verify the backup can be restored; do not overwrite the only copy.';return <main><PageHero eyebrow="Handover" title="Handover checklist and operating notes" description="A working handover template. Confirm host-specific items with the current administrator."/><section className="section"><div className="container handover-grid"><section className="soft-card"><h2>Checklist</h2>{items.map((x,i)=><label className="check-row" key={x}><input type="checkbox" checked={checks[i]} onChange={e=>setChecks(checks.map((v,j)=>j===i?e.target.checked:v))}/>{x}</label>)}<p>{checks.filter(Boolean).length} / {items.length} checked</p></section><section className="soft-card"><h2>Published reach · 2021–2023</h2><p>Program participants: 1,330</p><p>Young people engaged in dignified and fulfilling work: 253</p><p>Parents participating in weekly savings and lending meetings: 88</p><p>Adolescent girls regularly attending safe space meetings: 74</p><p>Countries: Uganda, Kenya, Tanzania, Ethiopia</p><small className="source-note">Source: crvpf.org/</small></section><section className="soft-card"><h2>Plugin list</h2><p>The live WordPress plugin list was not supplied. Confirm it from the admin installation before handover; no plugin names are assumed here.</p></section><section className="soft-card"><h2>Backup procedure</h2><ol className="numbered-list"><li>Back up both the WordPress database and files before updates.</li><li>Store a copy separately from the production host.</li><li>Record date and scope; verify restore steps on a safe environment.</li><li>Keep the previous known-good backup until the site is checked.</li></ol><button className="btn btn-outline" onClick={async()=>{try{await navigator.clipboard.writeText(backup);notify('Backup procedure copied.')}catch{notify('Clipboard is not available here.')}}}>Copy procedure</button></section></div></section></main>}
function Financial(){const lines=[['WordPress audit',1200000],['Design',2500000],['Homepage + Full Site',4500000],['Maps + SEO + Mailchimp',1800000],['Annual Report',850000],['Training',1200000]];const development=lines.reduce((sum,[,amount])=>sum+Number(amount),0);const total=development+1800000+500000;const payments=[['30%','Inception',total*.3],['30%','Homepage · 14 Dec',total*.3],['25%','Full Site · 31 Jan',total*.25],['15%','Handover',total*.15]];return <main><PageHero eyebrow="Financial" title="Project estimate" description="Amounts shown in UGX. Payment is due only on approval."/><section className="section"><div className="container"><div className="notice">All amounts are VAT inclusive as specified. The development subtotal is calculated from the listed line items.</div><div className="table-scroll"><table className="financial-table"><thead><tr><th>Category / item</th><th>Amount (UGX)</th></tr></thead><tbody><tr><th>A · Development</th><td>{development.toLocaleString()}</td></tr>{lines.map(([name,amount])=><tr key={String(name)}><td>{name}</td><td>{Number(amount).toLocaleString()}</td></tr>)}<tr><th>B · Support (UGX 180,000/month)</th><td>1,800,000</td></tr><tr><th>C · Third-party at cost</th><td>500,000</td></tr><tr className="total-row"><th>Total · VAT inclusive</th><td>{total.toLocaleString()}</td></tr></tbody></table></div><h2>Payment schedule · only on approval</h2><div className="financial-milestones">{payments.map(([percent,label,amount])=><article className="soft-card" key={label}><strong>{percent}</strong><span>{label}</span><b>UGX {Number(amount).toLocaleString()}</b></article>)}</div><p className="notice">The itemized development subtotal is UGX 12,050,000 (the brief’s “11,??” was a placeholder); with support and third-party costs the total is UGX 14,350,000.</p></div></section></main>}
function DonorPortal({notify,onDonate}:{notify:(s:string)=>void;onDonate:()=>void}){const[logged,setLogged]=useState(false),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState('');return <main><PageHero eyebrow="Donor Portal · demo" title="See the documented work" description="Demo access only. No donor accounts, contributions or private giving history are connected."/><section className="section"><div className="container">{!logged?<form className="soft-card form-stack donor-login" onSubmit={e=>{e.preventDefault();if(email==='demo@crvpf.org'&&password==='demo123'){setLogged(true);setError('')}else setError('Invalid demo credentials. Use demo@crvpf.org / demo123')}}><h2>Donor demo login</h2><label>Email<input className="field" type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="username"/></label><label>Password<input className="field" type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password"/></label>{error&&<div className="error-box" role="alert">{error}</div>}<button className="btn btn-green">Open demo portal</button></form>:<div className="soft-card"><h2>Donor Portal</h2><div className="donor-actions"><Link className="btn btn-green" href="/impact">See impact</Link><button className="btn btn-outline" onClick={()=>notify('Demo report download; no donor-specific report file was supplied.')}>Download report</button><button className="btn btn-orange" onClick={onDonate}>Donate again</button></div></div>}</div></section></main>}
function SystemPage(){
 const rows=[['Staff cannot publish','CMS 2-min publish'],['Partners cannot report','Partner Portal'],['Donors cannot see impact','Donor Portal + Annual Report'],['Safeguarding manual','4-check gate, Publish disabled until all ticked'],['Slow on data','Compressed images, lazy load, target <3s on MTN']];
 return <main><PageHero eyebrow="System Analysis" title="How This System Works - For CRVPF Staff & Board" description="System overview for the Replit proof of concept and proposed WordPress handover."/><section className="section"><div className="container"><section className="soft-card"><h2>5 problems → 5 solutions</h2><div className="table-scroll system-table-wrap"><table className="system-table"><thead><tr><th>Problem</th><th>Solution</th></tr></thead><tbody>{rows.map(([problem,solution])=><tr key={problem}><td>{problem}</td><td>{solution}</td></tr>)}</tbody></table></div><p className="notice">The under-three-second figure is a target on MTN mobile data, not an independently measured result. There is no live data in this Replit demo.</p></section><section className="soft-card" style={{marginTop:18}}><h2>Architecture</h2><p className="system-architecture">WordPress + Elementor → i3C Hosting → GA4 + Matomo → Daily Backup → 2FA</p><p>This architecture is the final WordPress plan. These integrations are not connected to the current Replit demo.</p></section><section className="soft-card" style={{marginTop:18}}><h2>Roles</h2><ul className="check-list"><li>Admin</li><li>Communications — approver</li><li>Editor</li><li>Partner — own grants only</li><li>Donor — read-only</li></ul></section><section className="soft-card" style={{marginTop:18}}><h2>Data rule</h2><p>Maps show district-level information only, never school or village locations.</p></section></div></section></main>
}
function HowWeDeliver(){
 const steps=[['1. Replit Demo = Proof','You can click, test CMS, test Partner Portal, and test the Safeguarding gate today, before you pay. This is a demo with no live data.'],['2. WordPress + i3C = Final Delivery','After approval, we rebuild 1-to-1 in WordPress + Elementor on i3C. You own domain, hosting, content, and users. We train staff to publish alone. We hand over passwords, backups, and SOPs.'],['3. Migration Plan','Week 1 Inception + Audit on i3C · Week 2-3 Homepage in WordPress staging · Week 4 Homepage live 14 Dec · Week 5-8 Full site 31 Jan · Feb-Nov Support + Monthly Reports.'],['4. What You Own','WordPress admin, Elementor templates, i3C hosting, GA4 analytics, Mailchimp audience, all photos + content. No lock-in to Replit, no lock-in to ELITECH.']];
 return <main><PageHero eyebrow="How We Deliver" title="How We Deliver" description="The demo and handover steps, with ownership and transfer boundaries stated clearly."/><section className="section"><div className="container"><div className="handover-grid">{steps.map(([title,text])=><article className="soft-card" key={title}><h2>{title}</h2><p>{text}</p></article>)}</div><section className="soft-card" style={{marginTop:18}}><h2>5. Transfer-Ready - No Lock-In</h2><p>This Replit demo is transfer-ready. Design, content, images, structure, and system logic will transfer 1-to-1 to WordPress + Elementor on i3C per TOR, or to any platform CRVPF chooses (Wix, Webflow, Custom). Replit code is not directly copied - it is rebuilt as WordPress theme + Elementor templates to ensure CRVPF owns everything.</p><div className="content-grid"><div><h3>What transfers</h3><ul className="check-list"><li>Design</li><li>Text from crvpf.org</li><li>Real CRVPF photos</li><li>Page structure</li><li>Safeguarding gate logic</li><li>Partner Portal logic</li><li>Map + Filters logic</li></ul></div><div><h3>What is rebuilt</h3><ul className="check-list"><li>Code as WordPress + Elementor</li><li>Real user accounts + 2FA</li><li>Real Mailchimp + GA4 connections</li><li>Daily i3C backup</li><li>You own domain, hosting, content, users.</li></ul></div></div><p className="notice">The Replit demo has no live WordPress, i3C, Mailchimp, GA4, or user-account connections.</p></section></div></section></main>
}
 function Contact({notify}:{notify:(s:string)=>void}){
 const [ok,setOk]=useState(false);
 const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;setOk(true);f.reset();notify('Your message is confirmed in this local demo. It was not sent.');};
  return <main><PageHero eyebrow="GET IN TOUCH" title="General Inquiries" description="Children's Rights and Violence Prevention Fund (CRVPF)"/><section className="section"><div className="container contact-grid"><aside className="soft-card"><div className="section-kicker">GET IN TOUCH</div><div className="contact-line"><Phone size={19}/><a href="tel:+256393216519">(+256) 393 216 519</a></div><div className="contact-line"><Mail size={19}/><a href="mailto:info@crvpf.org">info@crvpf.org</a></div><div className="contact-line"><MapPin size={19}/><span>Block 244, Plot 5170, Diplomate Road, Muyenga, Kampala, Uganda</span></div><a className="btn btn-green whatsapp-link" href="https://wa.me/256393216519" target="_blank" rel="noopener noreferrer">WhatsApp CRVPF</a><small className="source-note">Source: crvpf.org/</small><div className="notice">We do not publish children's personal details without consent.</div></aside><div className="soft-card">{ok&&<div className="success-box" role="status" style={{marginBottom:16}}>Thanks for your message. This is a local demo confirmation; no message was sent.</div>}<form className="form-stack" onSubmit={submit}><label>Your name<input className="field" name="name" required minLength={2} data-testid="input-contact-name"/></label><label>Email address<input className="field" name="email" type="email" required data-testid="input-contact-email"/></label><label>Subject<select className="field" name="subject" required defaultValue=""><option value="" disabled>Select a topic</option><option>General enquiry</option><option>Programme enquiry</option><option>Partnership enquiry</option></select></label><label>Message<textarea className="field" name="message" rows={5} required minLength={10} data-testid="input-contact-message"/></label><button className="btn btn-green" type="submit" data-testid="button-contact-submit">Send demo message <ArrowRight size={16}/></button><small>Submitting shows a local confirmation only. No message is sent.</small></form></div></div></section></main>
}
function SearchModal({value,setValue,results,onClose,onStorySelect}:{value:string;setValue:(v:string)=>void;results:readonly {url:string;label:string}[];onClose:()=>void;onStorySelect:()=>void}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true" aria-label="Search website"><div className="modal-head"><h2>Search CRVPF</h2><button className="icon-btn" onClick={onClose} aria-label="Close search"><X/></button></div><input autoFocus className="field" value={value} onChange={e=>setValue(e.target.value)} placeholder="Search pages, programmes, stories…" data-testid="input-search"/><div style={{marginTop:17}}>{results.length?results.map((result,i)=><Link key={`${result.url}-${result.label}-${i}`} href={result.url} onClick={()=>{const hash=result.url.split('#')[1];if(hash)onStorySelect();onClose();if(hash)window.setTimeout(()=>document.getElementById(decodeURIComponent(hash))?.scrollIntoView({block:'start'}),80)}} className="arrow-link" style={{display:'flex',padding:'11px 0',borderBottom:'1px solid #8CC63F'}}>{result.label}<ArrowRight size={14}/></Link>):<p>No site content matched that search.</p>}</div></div></div>}
function DonateModal({onClose,notify}:{onClose:()=>void;notify:(s:string)=>void}){const [amount,setAmount]=useState('100000'),[custom,setCustom]=useState('');const submit=(e:FormEvent)=>{e.preventDefault();if(amount==='custom'&&Number(custom)<1){notify('Enter a valid custom amount.');return}onClose();notify('Thank you - demo checkout')};return <Modal title="Support the work" onClose={onClose}><p>Demo checkout only; no payment is collected or processed.</p><form className="form-stack" onSubmit={submit}><div className="pin-buttons">{['50000','100000','250000','custom'].map(v=><button type="button" key={v} className={amount===v?'active':''} onClick={()=>setAmount(v)}>{v==='custom'?'Custom':`${Number(v).toLocaleString()} UGX`}</button>)}</div>{amount==='custom'&&<label>Custom amount (UGX)<input className="field" type="number" min="1" value={custom} onChange={e=>setCustom(e.target.value)} required/></label>}<button className="btn btn-orange" type="submit" data-testid="button-confirm-donate">Proceed <ArrowRight size={16}/></button></form></Modal>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal" role="dialog" aria-modal="true"><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Close dialog"><X/></button></div>{children}</div></div>}
function BackToTop(){const [visible,setVisible]=useState(false);useEffect(()=>{const check=()=>setVisible(window.scrollY>500);window.addEventListener('scroll',check,{passive:true});check();return()=>window.removeEventListener('scroll',check)},[]);return visible?<button className="btn back-to-top" aria-label="Back to top" title="Back to top" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})} data-testid="button-back-to-top" style={{position:'fixed',right:20,bottom:80,zIndex:34,width:48,height:48,borderRadius:50,border:'2px solid #FFFFFF',background:'#FCEE21',color:'#1A1A1A',boxShadow:'none',display:'grid',placeItems:'center'}}><ArrowUp size={19}/></button>:null}
function NotFound(){return <main><PageHero eyebrow="Not found" title="That page is not here." description="Use the navigation to explore CRVPF’s programmes, stories and publications."/><section className="section"><div className="container"><Link href="/" className="btn btn-blue">Back to home <ArrowRight size={16}/></Link></div></section></main>}

export default App;
